	SUBROUTINE KAYPRM
      CHARACTER*31 NAM2
	INTEGER*2 E,I
C
      CHARACTER*2 ID
	INTEGER*2 MHI,MLO,RNG,MENDS,IDA,MQD,TH,VH
	REAL*4 XD,SV,SND,AV,SE,MODE,MEDIAN
	COMMON/DOG/MHI(2),MLO(2),ID,XD,SV(2),SND(2,2),RNG(2),
     *MENDS(2),IDA(10),MQD(10),AV(2,2),SE(2,2),MODE(2,2),
     *MEDIAN(2,2),TH(10),VH(10)
C
	WRITE(*,1010)
	READ(*,1011)NAM2
	CALL UPPER(NAM2,31)
	OPEN(UNIT=1,FILE=NAM2,STATUS='OLD',
     *CARRIAGE CONTROL='FORTRAN',
     *FORM='FORMATTED')
	READ(1,*)NAM2
	READ(1,1012)I
 1012 FORMAT(37X,I3)
      READ(1,1030)XD,SV(1),SV(2)
	READ(1,1020)SND(1,1),SND(1,2),SND(2,1),SND(2,2)
	DO E=1,2
	   DO I=1,2
		READ(1,1042)
		READ(1,1040)(TH(K),K=1,10)
		READ(1,1041)(VH(K),K=1,10),AV(I,E),SE(I,E),
     *      MODE(I,E),MEDIAN(I,E)
	   END DO
	   READ(1,1042)
	   READ(1,1000)MHI(E),MLO(E),MENDS(E),RNG(E)
	END DO
	READ(1,1060)(MQD(I),I=1,10)
	READ(1,1060)(IDA(I),I=1,10)
	CLOSE(UNIT=1)
      RETURN
 1000 FORMAT(3X,3I6,I5)
 1010 FORMAT(1H&,'Enter KAYPRM filename: ')
 1011 FORMAT(A)
 1020 FORMAT(/3X,4(F7.3,3X))
 1030 FORMAT(6X,F8.4,F6.2,3X,F6.2,1X)
 1040 FORMAT(I7,9I6)
 1041 FORMAT(I7,9I6,/,20X,F8.1,F14.2,2F8.1/)
 1042 FORMAT()
 1050 FORMAT(2X,A1,3I6,I5)
 1060 FORMAT(5X,10I6)
	END
